from pager.pages import page, page_count

ITEMS = ["a", "b", "c", "d", "e"]


def test_page_count_for_full_pages() -> None:
    assert page_count(10, 5) == 2


def test_page_count_rounds_up_partial_pages() -> None:
    assert page_count(5, 2) == 3


def test_first_page() -> None:
    assert page(ITEMS, 1, 2) == ["a", "b"]


def test_last_partial_page() -> None:
    assert page(ITEMS, 3, 2) == ["e"]
